mapper.select:
SELECT id, doc_id, version, kb_id, tenant_id, user_id, agent_id, title, content,
       status, error_msg, created_at, updated_at
FROM kb_document
WHERE doc_id = #{docId}
  AND version = #{version}
  AND tenant_id = #{tenantId}
  AND user_id = #{userId}
LIMIT 1

SELECT MAX(version)
FROM kb_document
WHERE doc_id = #{docId}
  AND tenant_id = #{tenantId}
  AND user_id = #{userId}

mapper.update:
UPDATE kb_document
SET status = #{status},
    error_msg = #{errorMsg}
WHERE doc_id = #{docId}
  AND version = #{version}
  AND tenant_id = #{tenantId}
  AND user_id = #{userId}

UPDATE kb_document
SET status = 'ARCHIVED',
    error_msg = NULL
WHERE doc_id = #{docId}
  AND tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND status = 'SUCCESS'

mapper.select:
SELECT d.id, d.doc_id, d.version, d.kb_id, d.tenant_id, d.user_id, d.agent_id,
       d.title, NULL AS content, d.status, d.error_msg, d.created_at, d.updated_at
FROM kb_document d
INNER JOIN (
    SELECT doc_id, MAX(version) AS version
    FROM kb_document
    WHERE kb_id = #{kbId}
      AND tenant_id = #{tenantId}
      AND user_id = #{userId}
    GROUP BY doc_id
) latest ON latest.doc_id = d.doc_id AND latest.version = d.version
WHERE d.kb_id = #{kbId}
  AND d.tenant_id = #{tenantId}
  AND d.user_id = #{userId}
ORDER BY d.updated_at DESC
LIMIT 200

mapper.delete:
DELETE FROM kb_document
WHERE doc_id = #{docId}
  AND tenant_id = #{tenantId}
  AND user_id = #{userId}

DELETE FROM kb_document
WHERE kb_id = #{kbId}
  AND tenant_id = #{tenantId}
  AND user_id = #{userId}
